#!/usr/bin/env bash
set -euo pipefail


MODEL="${MODEL:-}"
if [[ -z "$MODEL" ]]; then
  echo "❌ MODEL is not set. Export it before running:" >&2
  echo '   export MODEL="..."' >&2
  exit 1
fi

# ---- HELPERS ---------------------------------------------------------------
urlencode() {
  local string="$1" encoded="" i char
  for (( i=0; i<${#string}; i++ )); do
    char="${string:i:1}"
    case "$char" in
      [a-zA-Z0-9._~-]) encoded+="$char" ;;
      *) printf -v encoded '%s%%%02X' "$encoded" "'$char" ;;
    esac
  done
  printf '%s' "$encoded"
}

# Validate the FIBO JSON prompt, fill the ${MODEL_LABEL}/${MODEL_PARAMS}/${STEPS}/${CFG}
# placeholders (used by 5A/5B) and compact it to a single line.
# Substitution happens inside jq so the values are JSON-escaped correctly.
fill_prompt() {
  jq -c \
    --arg label  "$MODEL_LABEL"  \
    --arg params "$MODEL_PARAMS" \
    --arg steps  "$STEPS"        \
    --arg cfg    "$CFG"          \
    'walk(if type == "string" then
            split("${MODEL_LABEL}")  | join($label)  |
            split("${MODEL_PARAMS}") | join($params) |
            split("${STEPS}")        | join($steps)  |
            split("${CFG}")          | join($cfg)
          else . end)' <<<"$1"
}

queue_job() {
  local index="$1"
  local id="$2"
  local prompt="$3"
  local negative="${4:-}"

  if ! prompt="$(fill_prompt "$prompt")"; then
    echo "❌ Prompt $id is not valid JSON — skipping." >&2
    return 1
  fi

  local short task_name
  short="$(jq -r '.short_description // ""' <<<"$prompt")"
  task_name="$(printf '%02d' "$index") ${id} ${short:0:16}"

  printf "[QUEUE %02d %s] %s…\n" "$index" "$id" "${short:0:120}"

  local json
  json=$(jq -n \
    --arg  prompt    "$prompt"    \
    --arg  negative  "$negative"  \
    --arg  sampler   "$SAMPLER"   \
    --arg  model     "$MODEL"     \
    --argjson steps   $STEPS      \
    --argjson cfg     $CFG        \
    --argjson ag      $AG         \
    --argjson w       $WIDTH      \
    --argjson h       $HEIGHT     \
    --argjson seed    $SEED       \
    '{
      sd_model_checkpoint: $model,
      checkpoint:           $model,
      prompt:          $prompt,
      negative_prompt: $negative,
      steps:           $steps,
      cfg_scale:       $cfg,
      pag_scale:       $ag,
      width:           $w,
      height:          $h,
      sampler_name:    $sampler,
      seed:            $seed,
      batch_size:      1,
      n_iter:          1,
      save_images:     true
    }')

  curl -s -X POST "$SCHED?name=$(urlencode "$task_name")" \
    -H "Content-Type: application/json" \
    -d "$json" > /dev/null
}

# ---- PROMPTS ---------------------------------------------------------------
# Source: https://wiki.liutyi.info/display/AI/liutyi+text2image+test+v1
# Structure: 12 rows (categories) × 4 columns (A–D) + 4 extra art style variants = 52 prompts
# Queued row-by-row: 1A 1B 1C 1D / 2A 2B … / 12A–12D / extra A–D
#
# Prompts are Bria FIBO structured (VGL) JSON, one compact JSON object per slot,
# converted from the plain-text prompts of test1.sh. Each is single-quoted so the
# shell leaves it untouched; placeholders are filled by fill_prompt() at queue time.
#
# Negative prompts are kept in a parallel negatives[] array (plain text).
# Empty string = no negative prompt for that slot.
#
# ⚠ PROMPTS 5A and 5B contain ${MODEL_LABEL}, ${MODEL_PARAMS}, ${STEPS} and ${CFG}
#   inside their text_render entries. They are substituted from the environment
#   variables of the same names (MODEL_LABEL, MODEL_PARAMS, STEPS, CFG).
#
# Row 8C was a danmaku-style prompt (score_N tags) for fine-tuned anime models;
# FIBO does not use those tags, so they are kept only as a note in artistic_style.
# ---------------------------------------------------------------------------
